    pub fn check_pdf_a_conformance(snapshot: &PdfSnapshot) -> Vec<Diagnostic> {
        let objects = &snapshot.objects;
        let mut out = Vec::new();
        if snapshot.encryption.is_some() {
            out.push(hard(CODE_ENCRYPT, "PDF/A forbids retained document encryption".into()));
