                all.extend(soft);
                return Err(ComposeError { message: format!("PDF/A conformance violated: {} hard issue(s) -- not stamping the a dialect", hard.len()), diagnostics: all });
            }
            let mut diagnostics = inner.diagnostics;
            diagnostics.extend(soft);
