    pub const CODE_FONT_NOT_EMBEDDED: &str = "stdio.pdf.a.font-not-embedded";
    pub const CODE_EMBEDDED_FILE_AFRELATIONSHIP: &str = "stdio.pdf.a.embedded-file-missing-afrelationship";
